<?php require_once 'layout.php'; require_user(); $db=db(); if ($_SERVER['REQUEST_METHOD']==='POST') { $id=(int)$_POST['item_id']; $uid=current_user()['id']; $s=$db->prepare('INSERT INTO cart_items(user_id,menu_item_id,quantity) VALUES(?,?,1) ON DUPLICATE KEY UPDATE quantity=quantity+1'); $s->bind_param('ii',$uid,$id); $s->execute(); flash('Item added to cart.'); redirect('menu.php'); } $cat=$_GET['cat']??'All'; $q=trim($_GET['q']??''); $cats=$db->query("SELECT DISTINCT category FROM menu_items WHERE is_active=1 ORDER BY category")->fetch_all(MYSQLI_ASSOC); if($cat==='All'){ $s=$db->prepare("SELECT * FROM menu_items WHERE is_active=1 AND name LIKE CONCAT('%',?,'%') ORDER BY id DESC"); $s->bind_param('s',$q); } else { $s=$db->prepare("SELECT * FROM menu_items WHERE is_active=1 AND category=? AND name LIKE CONCAT('%',?,'%') ORDER BY id DESC"); $s->bind_param('ss',$cat,$q); } $s->execute(); $items=$s->get_result(); page_header('Food Menu'); ?><div class="topbar"><h1>Food Menu</h1><form><input name="q" value="<?=h($q)?>" placeholder="Search food..."><input type="hidden" name="cat" value="<?=h($cat)?>"></form><a class="cart-link" href="cart.php">🛒 <span><?=cart_count(current_user()['id'])?></span></a></div><div class="tabs"><a class="<?= $cat==='All'?'active':'' ?>" href="menu.php?cat=All">All</a><?php foreach($cats as $c):?><a class="<?= $cat===$c['category']?'active':'' ?>" href="menu.php?cat=<?=urlencode($c['category'])?>"><?=h($c['category'])?></a><?php endforeach;?></div><section class="grid"><?php while($i=$items->fetch_assoc()):?><article class="food-card"><img src="<?=h($i['image']?:'assets/food.svg')?>" alt=""><h3><?=h($i['name'])?></h3><strong>₹<?=number_format($i['price'],0)?></strong><form method="post"><input type="hidden" name="item_id" value="<?=$i['id']?>"><button>Add to Cart</button></form></article><?php endwhile;?></section><?php page_footer(); ?>
